// Concatenates contrails-core.js and the js/*.js classic scripts, in load order, into app.bundle.js so the page
// makes one request for the app instead of ten. The scripts already share one global scope, so joining them
// changes nothing about how they run. The output is committed (GitHub Pages serves the repo as-is);
// `node smoke-boot.mjs` fails when it is stale, and scripts/dev-server.mjs rebuilds it on every request.
//
//   node scripts/build-bundle.mjs           # write app.bundle.js
//   node scripts/build-bundle.mjs --check   # exit 1 if app.bundle.js is out of date

import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";

const ROOT = new URL("..", import.meta.url);

export const BUNDLE_FILE = "app.bundle.js";

// Load order matters: declarations a file uses at top level must come from an earlier file; boot.js runs last.
export const BUNDLE_SOURCES = [
  "contrails-core.js",
  "js/app-core.js",
  "js/map.js",
  "js/features.js",
  "js/data.js",
  "js/render.js",
  "js/geolocation.js",
  "js/airport-board.js",
  "js/controls.js",
  "js/boot.js",
];

export async function buildBundle() {
  const parts = ["// Generated by scripts/build-bundle.mjs from " + BUNDLE_SOURCES.join(", ") + ". Do not edit.\n"];
  for (const src of BUNDLE_SOURCES) {
    const code = await readFile(new URL(src, ROOT), "utf8");
    // The leading ";" keeps a file that ends without one from running into the next file's first line.
    parts.push("\n;// ---- " + src + " ----\n" + code.replace(/\s*$/, "\n"));
  }
  return parts.join("");
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const bundle = await buildBundle();
  const target = new URL(BUNDLE_FILE, ROOT);
  if (process.argv.includes("--check")) {
    const current = await readFile(target, "utf8").catch(() => "");
    if (current !== bundle) {
      console.error(BUNDLE_FILE + " is out of date: run node scripts/build-bundle.mjs");
      process.exit(1);
    }
    console.log(BUNDLE_FILE + " is up to date.");
  } else {
    await writeFile(target, bundle);
    console.log("Wrote " + BUNDLE_FILE + " (" + bundle.length + " bytes).");
  }
}
